import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// ---------------------------------------------------------------------
// Vectorized (float4) LayerNorm kernel: one block per outer row (batch),
// normalization performed across the flattened inner dimension M
// (M must be divisible by 4).
// ---------------------------------------------------------------------
__global__ void layernorm_kernel_vec4(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int M, float eps)
{
  int n = blockIdx.x;
  int M4 = M >> 2;

  const float4* x_row = reinterpret_cast<const float4*>(X + (int64_t)n * M);
  float4*       y_row = reinterpret_cast<float4*>(Y + (int64_t)n * M);
  const float4* w_ptr  = reinterpret_cast<const float4*>(W);
  const float4* b_ptr  = reinterpret_cast<const float4*>(B);

  Tensor gX = make_tensor(make_gmem_ptr(x_row), make_shape(M4), make_stride(Int<1>{}));
  Tensor gY = make_tensor(make_gmem_ptr(y_row), make_shape(M4), make_stride(Int<1>{}));
  Tensor gW = make_tensor(make_gmem_ptr(w_ptr), make_shape(M4), make_stride(Int<1>{}));
  Tensor gB = make_tensor(make_gmem_ptr(b_ptr), make_shape(M4), make_stride(Int<1>{}));

  float sum = 0.f, sumsq = 0.f;
  for (int i = threadIdx.x; i < M4; i += blockDim.x) {
    float4 v = gX(i);
    sum   += v.x + v.y + v.z + v.w;
    sumsq += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
  }

  // warp-level reduction
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum   += __shfl_down_sync(0xffffffffu, sum, offset);
    sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
  }

  __shared__ float s_sum[32];
  __shared__ float s_sumsq[32];
  int lane = threadIdx.x & 31;
  int wid  = threadIdx.x >> 5;
  if (lane == 0) {
    s_sum[wid]   = sum;
    s_sumsq[wid] = sumsq;
  }
  __syncthreads();

  int numWarps = (blockDim.x + 31) >> 5;
  if (wid == 0) {
    sum   = (lane < numWarps) ? s_sum[lane]   : 0.f;
    sumsq = (lane < numWarps) ? s_sumsq[lane] : 0.f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      sum   += __shfl_down_sync(0xffffffffu, sum, offset);
      sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
    }
    if (lane == 0) {
      s_sum[0]   = sum;
      s_sumsq[0] = sumsq;
    }
  }
  __syncthreads();

  float mean    = s_sum[0] / (float)M;
  float var     = s_sumsq[0] / (float)M - mean * mean;
  float inv_std = rsqrtf(var + eps);

  for (int i = threadIdx.x; i < M4; i += blockDim.x) {
    float4 v = gX(i);
    float4 w = gW(i);
    float4 b = gB(i);
    float4 out;
    out.x = (v.x - mean) * inv_std * w.x + b.x;
    out.y = (v.y - mean) * inv_std * w.y + b.y;
    out.z = (v.z - mean) * inv_std * w.z + b.z;
    out.w = (v.w - mean) * inv_std * w.w + b.w;
    gY(i) = out;
  }
}

// ---------------------------------------------------------------------
// Scalar fallback kernel (works for any M), used when M is not
// divisible by 4.
// ---------------------------------------------------------------------
__global__ void layernorm_kernel_scalar(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int M, float eps)
{
  int n = blockIdx.x;

  const float* x_row = X + (int64_t)n * M;
  float*       y_row = Y + (int64_t)n * M;

  Tensor gX = make_tensor(make_gmem_ptr(x_row), make_shape(M), make_stride(Int<1>{}));
  Tensor gY = make_tensor(make_gmem_ptr(y_row), make_shape(M), make_stride(Int<1>{}));
  Tensor gW = make_tensor(make_gmem_ptr(W),     make_shape(M), make_stride(Int<1>{}));
  Tensor gB = make_tensor(make_gmem_ptr(B),     make_shape(M), make_stride(Int<1>{}));

  float sum = 0.f, sumsq = 0.f;
  for (int i = threadIdx.x; i < M; i += blockDim.x) {
    float v = gX(i);
    sum   += v;
    sumsq += v * v;
  }

  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum   += __shfl_down_sync(0xffffffffu, sum, offset);
    sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
  }

  __shared__ float s_sum[32];
  __shared__ float s_sumsq[32];
  int lane = threadIdx.x & 31;
  int wid  = threadIdx.x >> 5;
  if (lane == 0) {
    s_sum[wid]   = sum;
    s_sumsq[wid] = sumsq;
  }
  __syncthreads();

  int numWarps = (blockDim.x + 31) >> 5;
  if (wid == 0) {
    sum   = (lane < numWarps) ? s_sum[lane]   : 0.f;
    sumsq = (lane < numWarps) ? s_sumsq[lane] : 0.f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      sum   += __shfl_down_sync(0xffffffffu, sum, offset);
      sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
    }
    if (lane == 0) {
      s_sum[0]   = sum;
      s_sumsq[0] = sumsq;
    }
  }
  __syncthreads();

  float mean    = s_sum[0] / (float)M;
  float var     = s_sumsq[0] / (float)M - mean * mean;
  float inv_std = rsqrtf(var + eps);

  for (int i = threadIdx.x; i < M; i += blockDim.x) {
    float v = gX(i);
    float w = gW(i);
    float b = gB(i);
    gY(i) = (v - mean) * inv_std * w + b;
  }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();

  int64_t M64 = 1;
  int64_t wdims = w_c.numel();
  M64 = wdims;

  int64_t total = x_c.numel();
  TORCH_CHECK(total % M64 == 0, "x size incompatible with normalized_shape");
  int64_t N64 = total / M64;

  int M = (int)M64;
  int N = (int)N64;

  auto y = torch::empty_like(x_c);

  const float* x_ptr = x_c.data_ptr<float>();
  const float* w_ptr = w_c.data_ptr<float>();
  const float* b_ptr = b_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  int threads = 512;
  dim3 grid(N);
  dim3 block(threads);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (M % 4 == 0) {
    layernorm_kernel_vec4<<<grid, block, 0, stream>>>(
        x_ptr, w_ptr, b_ptr, y_ptr, M, (float)eps);
  } else {
    layernorm_kernel_scalar<<<grid, block, 0, stream>>>(
        x_ptr, w_ptr, b_ptr, y_ptr, M, (float)eps);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include", "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single fused custom CUDA/CuTe kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._ext = layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.weight,
            self.bias,
            float(self.eps),
        )

